import numpy as np
x=np.arange(1,11); labels=np.array([0,0,0,0,1,1,0,0,1,1])
def gini(v):
    p=np.bincount(v,minlength=2)/len(v)
    return 1-np.sum(p*p)
print('划分前:',gini(labels))
for threshold in [4.5,6.5]:
    left=labels[x<=threshold]; right=labels[x>threshold]
    quality=(len(left)*gini(left)+len(right)*gini(right))/len(labels)
    print('阈值、子节点加权不纯度、减少量:',threshold,quality,gini(labels)-quality)

